import{_ as r,o as t,c as o,ag as l}from"./chunks/framework.DzGOF12C.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/China/07-Buddhism.md","filePath":"philosophy/China/07-Buddhism.md"}'),s={name:"philosophy/China/07-Buddhism.md"};function i(n,a,e,h,p,d){return t(),o("div",null,[...a[0]||(a[0]=[l('<h2 id="브라마니즘과-불교의-핵심-차이점" tabindex="-1">브라마니즘과 불교의 핵심 차이점 <a class="header-anchor" href="#브라마니즘과-불교의-핵심-차이점" aria-label="Permalink to &quot;브라마니즘과 불교의 핵심 차이점&quot;">​</a></h2><h3 id="_1-존재의-실체-아트만-vs-무아" tabindex="-1">1. 존재의 실체: 아트만 vs 무아 <a class="header-anchor" href="#_1-존재의-실체-아트만-vs-무아" aria-label="Permalink to &quot;1. 존재의 실체: 아트만 vs 무아&quot;">​</a></h3><ul><li><strong>브라마니즘:</strong> 인간 내면에는 환경이나 시간에 따라 절대 변하지 않는 영원불변의 독자적 영혼이자 자아인 &#39;아트만&#39;이 실재한다고 보았습니다.</li><li><strong>불교:</strong> 영원한 자아란 인간의 착각일 뿐이며, 인간은 오온(육체와 정신 작용)이 일시적으로 결합한 존재로서 고정된 알맹이가 없다는 &#39;무아설(無我說)&#39;을 주장했습니다.</li></ul><h3 id="_2-세계의-본질-범아일여-vs-연기설" tabindex="-1">2. 세계의 본질: 범아일여 vs 연기설 <a class="header-anchor" href="#_2-세계의-본질-범아일여-vs-연기설" aria-label="Permalink to &quot;2. 세계의 본질: 범아일여 vs 연기설&quot;">​</a></h3><ul><li><strong>브라마니즘:</strong> 우주의 근본 실체인 &#39;브라흐만&#39;과 개인의 실체인 &#39;아트만&#39;이 본래 하나라는 &#39;범아일여(梵我一如)&#39;를 주장했습니다. 내가 곧 우주의 절대적 실체라는 철학입니다.</li><li><strong>불교:</strong> 우주든 개인이든 독립된 고정 실체는 존재하지 않으며, 모든 것은 오직 인연(원인과 조건)에 의해 서로 연결되어 끊임없이 변화할 뿐이라는 &#39;연기설(緣起說)&#39;로 맞섰습니다.</li></ul><h3 id="_3-해탈의-시기-내세-vs-현세" tabindex="-1">3. 해탈의 시기: 내세 vs 현세 <a class="header-anchor" href="#_3-해탈의-시기-내세-vs-현세" aria-label="Permalink to &quot;3. 해탈의 시기: 내세 vs 현세&quot;">​</a></h3><ul><li><strong>브라마니즘:</strong> 영혼을 가두고 있는 육체를 벗어난 사후 세계, 즉 내세(來世)에 이르러서야 비로소 브라흐만과 완벽히 합일하는 궁극적인 해탈이 이루어진다고 믿었습니다.</li><li><strong>불교:</strong> 해탈은 사후의 일이 아닙니다. 지금 이 순간 내 마음의 무명(어리석음)을 깨트리면, 살아있는 현재인 현세(現世)에서 곧바로 모든 고통이 사라진 해탈(열반)을 이룰 수 있다고 보았습니다.</li></ul><h3 id="_4-수행의-방법-고행주의-vs-중도" tabindex="-1">4. 수행의 방법: 고행주의 vs 중도 <a class="header-anchor" href="#_4-수행의-방법-고행주의-vs-중도" aria-label="Permalink to &quot;4. 수행의 방법: 고행주의 vs 중도&quot;">​</a></h3><ul><li><strong>브라마니즘:</strong> 육체를 영혼의 감옥이자 번뇌의 원인으로 여겼기 때문에, 육체적 본능을 말살하기 위한 극단적인 <strong>고행</strong>을 필수적인 수행법으로 강조했습니다.</li><li><strong>불교:</strong> 육체를 무의미하게 학대하는 고행주의와 본능에 휩쓸리는 쾌락주의를 모두 배격했습니다.</li></ul><h2 id="_1-연기설-緣起說-12연기-유전문-12緣起-流轉門" tabindex="-1">1. 연기설 (緣起說) &amp; 12연기 유전문 (12緣起 流轉門) <a class="header-anchor" href="#_1-연기설-緣起說-12연기-유전문-12緣起-流轉門" aria-label="Permalink to &quot;1. 연기설 (緣起說) &amp; 12연기 유전문 (12緣起 流轉門)&quot;">​</a></h2><p>인간 존재의 변화 과정을 <strong>시간적 순환 경로</strong>로 설명한 법칙입니다.</p><ul><li><p><strong>발생 메커니즘:</strong> 무명(無明)에서 시작하여 노사(老死)의 괴로움에 이르는 12가지 단계가 순차적으로 맞물려 돌아갑니다.</p></li><li><p><strong>고통의 근원:</strong> 인간의 근본 고통은 무명(밝음이 없음)에서 비롯됩니다.</p></li><li><p><strong>밝음(지혜)의 실체:</strong> 여기서 깨달아야 할 &#39;밝음&#39;이란 &quot;세계에 고정불변하는 독립된 실체는 없다&quot;는 진리입니다. 불교적 사유는 바로 이 연기적 진리를 철저히 인식하는 것에서 출발합니다</p></li></ul><h2 id="_2-무아설-無我說-윤회-輪廻" tabindex="-1">2. 무아설 (無我說) &amp; 윤회 (輪廻) <a class="header-anchor" href="#_2-무아설-無我說-윤회-輪廻" aria-label="Permalink to &quot;2. 무아설 (無我說) &amp; 윤회 (輪廻)&quot;">​</a></h2><p>고정된 자아(아, 我)가 없다는 무아설과 과거의 행위가 미래에 영향을 미친다는 업설의 모순을 설명하는 핵심 논리입니다.</p><ul><li><p><strong>질문:</strong> 업(業, 행위)을 지은 자와 그에 따른 보(報, 결과)를 받는 자는 동일인인가?</p></li><li><p><strong>답변:</strong> 완전히 같은 존재도 아니고, 완전히 다른 존재도 아닙니다(<strong>불일불이, 不一不異</strong>).</p></li><li><p><strong>메커니즘:</strong> 고정된 영혼이 이동하는 것이 아니라, 행위의 데이터인 <strong>&#39;업(業)&#39;이 정신적 주체인 &#39;식(識)&#39;에 저장되어 상속</strong>됩니다. 마치 한 촛불이 다른 초로 옮겨 붙을 때, 불꽃의 형태와 성질은 이어지지만 이전의 초와 이후의 초가 물리적으로 동일하지 않은 것과 같습니다.</p></li><li><p><strong>해탈(解脫)의 가능성:</strong> 과거에 지은 업의 결과는 바꿀 수 없지만, 현재 순간에 <strong>무명에서 벗어나 지혜를 밝히면</strong> 과거의 보를 온전히 감당해 내는 동시에 더 이상 새로운 악업을 짓지 않게 됩니다. 이로써 인과의 사슬을 끊고 해탈에 다다를 수 있습니다.</p></li></ul><h2 id="_3-오온-五蘊-18계-十八界" tabindex="-1">3. 오온 (五蘊) &amp; 18계 (十八界) <a class="header-anchor" href="#_3-오온-五蘊-18계-十八界" aria-label="Permalink to &quot;3. 오온 (五蘊) &amp; 18계 (十八界)&quot;">​</a></h2><p>인간을 구성하는 5가지 요소</p><p>색수상행식<br> 색은 인간의 물질적 요소를 수, 상, 행, 식은 인간의 작용을 의미함</p><p>수는 감각 작용, 상은 표상작용, 행은 상을 읽으려는 마음의 작용, 식은 인식작용이다.</p><p>고정된 &#39;나&#39;라는 자아가 있어서 앞에 있는 꽃을 관찰하는 것이 아님.<br> 꽃이라는 대상과 감각기관이 만나 &#39;꽃을 인식하는 작용(식)&#39;이 일어날 때, 그 순간의 연기적 결합 자체가 바로 &#39;나&#39;라는 존재의 실체.</p><p>모든 것은 연기적이고 실제적인 것은 없다.</p><h3 id="_18계-인식-세계의-확장" tabindex="-1">18계 (인식 세계의 확장) <a class="header-anchor" href="#_18계-인식-세계의-확장" aria-label="Permalink to &quot;18계 (인식 세계의 확장)&quot;">​</a></h3><p>오온을 감각기관을 기준으로 나누면 육입으로 구분지을 수 있음<br> 안이비설신의<br> 이 감각 구조가 대상 및 의식과 결합하여 총 18가지 인식 세계를 이룸</p><p>안이비설신의 로 구분짓는다.</p><p>이는 감각기관과 인식기관인 육근, 감각대상인 육경, 그로인한 의식인 육식으로 나뉘며 이를 인간의 인식 세계를 구성하는 18가지 요소 18계로 부름</p><h2 id="_4-사성제-四聖諦" tabindex="-1">4. 사성제 (四聖諦) <a class="header-anchor" href="#_4-사성제-四聖諦" aria-label="Permalink to &quot;4. 사성제 (四聖諦)&quot;">​</a></h2><p>네가지의 성스러운 진리라는 의미<br> 고성제 집성제 멸성제 도성제로 구분됨</p><p>고성제: 인간의 삶이 본질적으로 괴로움이라는 진리</p><p>집성제: 그 괴로움의 원인이 집착에 의한 것이라는 진리<br> 멸성제: 집착을 끊으면 괴로움이 사라질수 있다는 진리<br> 도성제: 그러한 소멸로 가는 실천적 방법이 있다는 진리<br> 팔정도 제시. 정어, 정명, 정사, 정견 등등 구체적 실천 방법 8개를 제시함</p><h2 id="_5-삼법인설" tabindex="-1">5. 삼법인설 <a class="header-anchor" href="#_5-삼법인설" aria-label="Permalink to &quot;5. 삼법인설&quot;">​</a></h2><p>불교의 세 가지 절대적인 법칙</p><h3 id="_1-제행무상-諸行無常" tabindex="-1">1. 제행무상 (諸行無常) <a class="header-anchor" href="#_1-제행무상-諸行無常" aria-label="Permalink to &quot;1. 제행무상 (諸行無常)&quot;">​</a></h3><ul><li><strong>정의:</strong> 조건에 의해 형성된 모든 현상(제행)은 영원하지 않고 항상 변한다(무상).</li><li><strong>핵심:</strong> 물질적 존재는 물론, 인간의 감정, 생각, 가치관, 권력, 사회적 위치 등 세상 모든 것은 단 한 순간도 고정되어 있지 않고 생성·소멸을 반복합니다.</li></ul><h3 id="_2-제법무아-諸法無我" tabindex="-1">2. 제법무아 (諸法無我) <a class="header-anchor" href="#_2-제법무아-諸法無我" aria-label="Permalink to &quot;2. 제법무아 (諸法無我)&quot;">​</a></h3><ul><li><strong>정의:</strong> 우주 만물과 모든 현상(제법)에는 고정불변하는 독립적인 실체나 자아(무아)가 없다.</li><li><strong>핵심:</strong> &#39;나&#39;라는 존재 역시 오온(색·수·상·행·식)의 일시적인 연기적 결합일 뿐, 그 기저에 영원히 변하지 않는 영혼이나 핵심 알맹이는 존재하지 않습니다. 앞서 언급한 &quot;세계의 고정된 실체가 없다&quot;는 명제와 완전히 일치합니다.</li></ul><h3 id="_3-일체개고-一切皆苦" tabindex="-1">3. 일체개고 (一切皆苦) <a class="header-anchor" href="#_3-일체개고-一切皆苦" aria-label="Permalink to &quot;3. 일체개고 (一切皆苦)&quot;">​</a></h3><ul><li><strong>정의:</strong> 모든 현상과 존재는 본질적으로 결국 괴로움(고)이다.</li><li><strong>핵심:</strong> 이 고통은 세상이 악해서가 아니라 인간의 정신적 오류에서 발생합니다. 세상은 끊임없이 변하고(무상) 내 마음대로 통제할 수 있는 실체도 없는데(무아), 인간은 그것이 영원하기를 바라고 소유하려 집착(무명)하기 때문에 결국 좌절과 괴로움에 직면하게 된다는 뜻입니다.</li></ul>',37)])])}const _=r(s,[["render",i]]);export{g as __pageData,_ as default};
